const SB = 'https://ssuikijiaulfhfxzwrgu.supabase.co/rest/v1/rpc/';
const ANON = '<<REDACTED>>';
const TOKEN = '<<IRIS_TOKEN>>';
const H = { apikey: ANON, Authorization: 'Bearer ' + ANON, 'Content-Type': 'application/json' };
const self = this;
// Always the previous completed session: step back one day, then skip weekends. The free tier serves
// end-of-day data once a session has settled (next day), so asking for today is rejected.
var d = new Date(Date.now() - 86400000);
while (d.getUTCDay() === 0 || d.getUTCDay() === 6) { d = new Date(d.getTime() - 86400000); }
var key = '';
try {
  var r = await self.helpers.httpRequest({ method: 'POST', url: SB + 'iris_secret_get', headers: H, body: { p_token: TOKEN, p_name: 'PRICE_API_KEY', p_source: 'price-feed' }, json: true, timeout: 15000 });
  key = (typeof r === 'string') ? r : (r && r.value ? r.value : '');
} catch (e) { key = ''; }
return [{ json: { d: d.toISOString().slice(0, 10), key: String(key || '') } }];

var r = $input.first().json || {};
var d = $('Plan Price Date').first().json.d;
var st = String(r.status || "");
var msg = String(r.message || r.error || "");
var res = r.results || [];

if (!res.length) {
  var keyProblem = st.toUpperCase() === "ERROR" || st.toUpperCase().indexOf("NOT_AUTHORIZED") >= 0 ||
    msg.toUpperCase().indexOf("UNKNOWN API KEY") >= 0 || msg.toUpperCase().indexOf("NOT ENTITLED") >= 0 || msg.toUpperCase().indexOf("UNAUTHORIZED") >= 0;
  var why;
  if (keyProblem) {
    why = "PRICE_API_KEY rejected by Massive (status=" + st + ", message=" + (msg || "none") + "). No prices were loaded for " + d + ". Owner action: create a free Stocks Basic key at massive.com and set the n8n variable PRICE_API_KEY.";
  } else if (st.toUpperCase() === "OK" || st.toUpperCase() === "DELAYED") {
    why = "Grouped daily answered OK with zero results for " + d + " - a market holiday is the usual cause; unverified.";
  } else {
    why = "Grouped daily returned no rows for " + d + " (status=" + st + ", message=" + (msg || "none") + ").";
  }
  return [{ json: { chunk: [], idx: 0, total: 0, n: 0, d: d, degraded: true, key_error: keyProblem, reason: why } }];
}

var rows = [];
for (var i = 0; i < res.length; i++) {
  var x = res[i];
  if (!x || !x.T) { continue; }
  if (x.c === undefined || x.c === null) { continue; }
  rows.push({ ticker: String(x.T).toUpperCase(), d: d, close: x.c, volume: (x.v === undefined || x.v === null) ? null : Math.round(x.v), source: "massive:grouped-daily" });
}

var size = 3000;
var out = [];
var total = Math.ceil(rows.length / size);
for (var c = 0; c < total; c++) {
  out.push({ json: { chunk: rows.slice(c * size, (c + 1) * size), idx: c, total: total, n: rows.length, d: d, degraded: false, key_error: false, reason: null } });
}
if (!out.length) {
  out.push({ json: { chunk: [], idx: 0, total: 0, n: 0, d: d, degraded: true, key_error: false, reason: "Response had results but none carried a ticker and close price." } });
}
return out;

var chunks = $('Map & Chunk Prices').all();
var ups = $input.all();
var loaded = 0;
for (var i = 0; i < ups.length; i++) { var j = ups[i].json || {}; loaded = loaded + (j.rows || 0); }
var first = chunks.length ? (chunks[0].json || {}) : {};
var degraded = first.degraded ? true : false;
return [{ json: { loaded: loaded, offered: first.n || 0, chunks: chunks.length, d: first.d || null, degraded: degraded, key_error: first.key_error ? true : false, reason: first.reason || null, ok: (!degraded && loaded > 0) } }];
